14	    color: #1c1917;
15	  }
16	  main { max-width: 32rem; margin: 0 auto; }
17	  h1 { font-size: 1.5rem; margin: 0 0 1rem; }
18	  form { display: flex; gap: 0.5rem; }
19	  input {
20	    flex: 1;
21	    min-width: 0;
22	    padding: 0.5rem 0.75rem;
23	    font: inherit;
24	    border: 1px solid #d6d3d1;
25	    border-radius: 6px;
26	  }
27	  button {
28	    padding: 0.5rem 1rem;
29	    font: inherit;
30	    border: 0;
31	    border-radius: 6px;
32	    background: #1c1917;
33	    color: #fff;
34	    cursor: pointer;
35	  }
36	  ul { list-style: none; margin: 1rem 0 0; padding: 0; }
37	  li {
38	    display: flex;
39	    align-items: center;
40	    gap: 0.5rem;
41	    padding: 0.5rem 0.75rem;
42	    margin-bottom: 0.5rem;
43	    background: #fff;
44	    border: 1px solid #e7e5e4;
45	    border-radius: 6px;
46	  }
47	  li span { flex: 1; overflow-wrap: anywhere; }
48	  li button { background: transparent; color: #b91c1c; padding: 0.25rem 0.5rem; }
49	  li input[type="checkbox"] { flex: none; width: 1.1rem; height: 1.1rem; margin: 0; }
50	  li[data-completed="true"] span { text-decoration: line-through; color: #78716c; }
51	  form input[type="date"] { flex: none; }
52	  .due { flex: none; font-size: 0.875rem; color: #57534e; }
53	  li[data-overdue="true"] { border-color: #fca5a5; background: #fef2f2; }
54	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
