60	<body>
61	<main>
62	  <h1>Todos</h1>
63	  <form id="add-form">
64	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
65	    <input data-testid="todo-due" type="date" aria-label="Due date">
66	    <button data-testid="todo-add" type="submit">Add</button>
67	  </form>
68	  <div class="filters" role="group" aria-label="Filter todos">
69	    <button data-testid="filter-all" data-filter="all" type="button" aria-pressed="true">All</button>
70	    <button data-testid="filter-active" data-filter="active" type="button" aria-pressed="false">Active</button>
71	    <button data-testid="filter-completed" data-filter="completed" type="button" aria-pressed="false">Completed</button>
72	  </div>
73	  <ul data-testid="todo-list"></ul>
74	</main>
75	<script src="todo-logic.js"></script>
76	<script>
77	(function () {
78	  var STORAGE_KEY = 'todos';
79	  var form = document.getElementById('add-form');
80	  var input = document.querySelector('[data-testid="todo-input"]');
81	  var dueInput = document.querySelector('[data-testid="todo-due"]');
82	  var list = document.querySelector('[data-testid="todo-list"]');
83	
84	  function load() {
85	    try {
86	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
87	      return Array.isArray(data) ? data : [];
88	    } catch (e) {
89	      return [];
90	    }
91	  }
92	
93	  function save() {
94	    try {
95	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
96	    } catch (e) {}
97	  }
98	
99	  function newId() {
100	    if (window.crypto && typeof crypto.randomUUID === 'function') {
101	      return crypto.randomUUID();
102	    }
103	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
104	  }
105	
106	  function render() {
107	    renderedDay = TodoLogic.localToday();
108	    list.textContent = '';
109	    filterButtons.forEach(function (btn) {
110	      btn.setAttribute('aria-pressed', String(btn.dataset.filter === filter));
111	    });
112	    TodoLogic.visibleTodos(todos, filter).forEach(function (todo) {
113	      var li = document.createElement('li');
114	      li.setAttribute('data-testid', 'todo-item');
115	      li.dataset.id = todo.id;
116	      li.setAttribute('data-completed', String(!!todo.completed));
117	      li.setAttribute('data-overdue', String(TodoLogic.isOverdue(todo, renderedDay)));
118	
119	      var toggle = document.createElement('input');
120	      toggle.type = 'checkbox';
121	      toggle.setAttribute('data-testid', 'todo-toggle');
122	      toggle.setAttribute('aria-label', 'Mark complete');
123	      toggle.checked = !!todo.completed;
124	      toggle.addEventListener('change', function () {
125	        todo.completed = toggle.checked;
126	        save();
127	        render();
128	      });
129	
130	      var text = document.createElement('span');
131	      text.setAttribute('data-testid', 'todo-text');
132	      text.textContent = todo.text;
133	
134	      var del = document.createElement('button');
135	      del.type = 'button';
136	      del.setAttribute('data-testid', 'todo-delete');
137	      del.setAttribute('aria-label', 'Delete');
138	      del.textContent = 'Delete';
139	      del.addEventListener('click', function () {
140	        todos = todos.filter(function (t) { return t.id !== todo.id; });
141	        save();
142	        render();
143	      });
144	
145	      li.appendChild(toggle);
146	      li.appendChild(text);
147	      if (todo.due) {
148	        var due = document.createElement('span');
149	        due.className = 'due';
150	        due.setAttribute('data-testid', 'todo-due-label');
151	        due.textContent = 'Due ' + todo.due;
152	        li.appendChild(due);
153	      }
154	      li.appendChild(del);
155	      list.appendChild(li);
156	    });
157	  }
158	
159	  var todos = load();
160	  var filter = 'all';
161	  var renderedDay = '';
162	  var filterButtons = Array.prototype.slice.call(document.querySelectorAll('[data-filter]'));
163	
164	  filterButtons.forEach(function (btn) {
165	    btn.addEventListener('click', function () {
166	      filter = btn.dataset.filter;
167	      render();
168	    });
169	  });
170	
171	  form.addEventListener('submit', function (event) {
172	    event.preventDefault();
173	    var text = input.value.trim();
174	    if (!text) return;
175	    var todo = { id: newId(), text: text, createdAt: Date.now(), completed: false };
176	    if (/^\d{4}-\d{2}-\d{2}$/.test(dueInput.value)) todo.due = dueInput.value;
177	    todos.push(todo);
178	    save();
179	    render();
180	    input.value = '';
181	    dueInput.value = '';
182	    input.focus();
183	  });
184	
185	  // Re-render when the local day changes so overdue flags stay current.
186	  setInterval(function () {
187	    if (TodoLogic.localToday() !== renderedDay) render();
188	  }, 60000);
189	
190	  render();
191	})();
192	</script>
193	</body>
194	</html>
